const OWNER_TYPES={balanced:{name:'Balanced Owner',description:'Build steady financial growth and compete for playoff appearances.',patience:80},tycoon:{name:'Win-At-All-Costs Tycoon',description:'Titles come first. Luxury-tax spending is acceptable when it builds a champion.',patience:65},penny:{name:'Penny-Pincher',description:'Protect margins and control payroll—even when competing for a playoff berth.',patience:75},hometown:{name:'Hometown Fan',description:'Fill the arena, keep franchise favorites, and reward local loyalty.',patience:80},rebuilder:{name:'Process-Truster',description:'Patient with losses when young players develop and the roster gains future value.',patience:90}};
const OWNER_GOAL_KINDS=['wins','playoffs','final','title','tax','cut','efficient','attendance','merch','tickets','star','retain','homegrown','rookie','young','profit'];
function ownerPayroll(club){return club.roster.reduce((n,p)=>n+p.salary,0)}
function ownerGames(club){return state.schedule.filter(r=>r.some(pair=>pair.includes(club.id))).length}
function ownerBaselineAttendance(club){return {Small:.78,Medium:.84,Large:.88}[club.marketSize]||.84}
function ownerBusinessProjection(club,plan){const ratio=club.w/(club.w+club.l||2),star=Math.max(...club.roster.map(p=>p.ovr)),loyal=club.roster.some(p=>p.id===plan.icon)? .025:0;return {attendance:Math.max(.4,Math.min(1,ownerBaselineAttendance(club)+(ratio-.5)*.2+Math.max(0,star-80)*.006+loyal-(plan.ticketPrice/plan.baseTicket-1)*.3)),merchPerHome:.22*(1+Math.max(0,star-75)*.04+ratio*.4)}}
function ownerFor(club){if(!club.owner){let hash=0;for(const c of club.key||club.abbr)hash=(Math.imul(hash,31)+c.charCodeAt(0))>>>0;const type=Object.keys(OWNER_TYPES)[Math.floor(Math.random()*Object.keys(OWNER_TYPES).length)];club.owner={type,patience:OWNER_TYPES[type].patience,fired:false,history:[],campaign:{startYear:state.year,baseWins:club.w,baseGames:ownerGames(club),settled:[]},plan:null}}if(!club.owner.plan||club.owner.plan.year!==state.year)club.owner.plan=ownerNewPlan(club);return club.owner}
function ownerNewPlan(club){const owner=club.owner,pay=ownerPayroll(club),games=ownerGames(club),remaining=state.schedule.slice(state.day).filter(r=>r.some(p=>p.includes(club.id))).length,icon=[...club.roster].sort((a,b)=>b.ovr-a.ovr)[0],previous=owner.history.at(-1);const plan={year:state.year,startDay:state.day,lastDay:state.day,basePayroll:pay,maxPayroll:pay,baseTicket:75,ticketPrice:75,initialIds:club.roster.map(p=>p.id),icon:icon?.id??0,iconTerm:icon?.contractThrough??state.year,star:icon?.ovr>=90?icon.id:null,adapted:false,homeGames:0,games:0,attendanceSum:0,ticketSum:0,merch:0,revenue:0,costs:0,goals:[]};
 plan.baseMerch=previous?.merchPerHome||ownerBusinessProjection(club,plan).merchPerHome;
 const add=(kind,target,weight=15,deadline=seasonLength())=>plan.goals.push({kind,target,weight,deadline,status:'pending'});
 const threshold=fraction=>Math.min(games,club.w+Math.ceil(remaining*fraction));
 if(owner.type==='balanced'){add('profit',0,20);add('playoffs',1,15);add('wins',threshold(.5),12)}
 if(owner.type==='tycoon'){add('title',1,30,seasonLength()+1);add('wins',threshold(.6),20);add('star',1,12);add('merch',1.15,10)}
 if(owner.type==='penny'){add('tax',salaryCap()*1.1,25);add('efficient',Math.min(10,state.teams.length),20);if(pay>salaryCap()*.7&&state.day<seasonLength()*.5)add('cut',Math.max(0,pay-20),15,Math.ceil(seasonLength()*.6));else add('profit',0,15);add('tickets',1.1,10)}
 if(owner.type==='hometown'){if(icon)add('retain',1,25,seasonLength()+1);add('attendance',.95,20);add('playoffs',1,15);const homegrown=club.roster.filter(p=>p.bio?.draftTeam===club.abbr);add(homegrown.length>=3?'homegrown':'wins',homegrown.length>=3?3:threshold(.5),12)}
 if(owner.type==='rebuilder'){add('young',Math.min(3,Math.max(1,club.roster.filter(p=>p.age<=25).length)),25);add('tax',salaryCap()*1.1,15);const rookie=club.roster.find(p=>p.bio?.draftRound===1&&p.bio?.draftYear>=state.year-1);add(rookie?'rookie':'wins',rookie?rookie.id:threshold(.3),12);add('profit',0,10)}
 return plan;
}
function ownerPlayoffClub(club){return rank().slice(0,4).some(t=>t.id===club.id)}
function ownerMPG(p,club,plan){const rows=state.history.filter(g=>g.day>plan.startDay&&(g.a===club.id||g.b===club.id)&&g.stage==='Regular season').flatMap(g=>g.box.filter(r=>r.playerId===p.id&&r.team===club.abbr&&r.played!==false));return rows.length&&rows.every(r=>Number.isFinite(r.mp))?rows.reduce((n,r)=>n+r.mp,0)/rows.length:0}
function ownerGoalProgress(club,goal){const plan=ownerFor(club).plan,roster=club.roster;switch(goal.kind){case 'wins':return club.w;case 'playoffs':return +ownerPlayoffClub(club);case 'final':return +state.history.some(g=>g.stage==='Championship'&&(g.a===club.id||g.b===club.id));case 'title':return +(state.champion===club.id);case 'tax':return plan.maxPayroll;case 'cut':return ownerPayroll(club);case 'efficient':return ownerPlayoffClub(club)?[...state.teams].sort((a,b)=>ownerPayroll(a)-ownerPayroll(b)||a.id-b.id).findIndex(t=>t.id===club.id)+1:state.teams.length+1;case 'attendance':return plan.homeGames?plan.attendanceSum/plan.homeGames:0;case 'merch':return plan.homeGames?plan.merch/plan.homeGames/plan.baseMerch:0;case 'tickets':return plan.homeGames&&plan.attendanceSum/plan.homeGames>=.85?plan.ticketSum/plan.homeGames/plan.baseTicket:0;case 'star':return +roster.some(p=>p.ovr>=85&&!plan.initialIds.includes(p.id));case 'retain':return +roster.some(p=>p.id===plan.icon&&(plan.iconTerm>plan.year||(p.contractThrough??plan.year)>plan.iconTerm));case 'homegrown':return roster.filter(p=>p.bio?.draftTeam===club.abbr&&ownerMPG(p,club,plan)>=15).length;case 'rookie':return roster.some(p=>p.id===goal.target&&ownerMPG(p,club,plan)>=20)?goal.target:-1;case 'young':return roster.filter(p=>p.age<=25&&ownerMPG(p,club,plan)>=20).length;case 'profit':return plan.revenue-plan.costs}}
function ownerGoalMet(club,g){const value=ownerGoalProgress(club,g);return ['tax','cut','efficient'].includes(g.kind)?value<=g.target:value>=g.target}
function ownerGoalLabel(club,g){const plan=ownerFor(club).plan;return {wins:'Win '+g.target+' games',playoffs:'Qualify for the four-team playoffs',final:'Reach the championship game',title:'Win the championship',tax:'Keep tracked payroll at or below '+money(g.target),cut:'Cut payroll to '+money(g.target)+' by day '+g.deadline,efficient:'Reach playoffs with a bottom-'+g.target+' payroll',attendance:'Average 95% arena attendance',merch:'Grow merchandise per home game by 15%',tickets:'Raise average ticket price 10% and keep attendance ≥85%',star:'Acquire a new 85+ OVR player',retain:'Keep '+(club.roster.find(p=>p.id===plan.icon)?.name||'the franchise face')+(plan.iconTerm<=plan.year?' and extend their contract':' under contract'),homegrown:'Play three homegrown players at least 15 MPG',rookie:'Give the first-round rookie at least 20 MPG',young:'Give '+g.target+' players age 25 or younger at least 20 MPG',profit:'Avoid an operating loss'}[g.kind]}
function ownerGoalDisplay(club,g){const v=ownerGoalProgress(club,g);if(['tax','cut','profit'].includes(g.kind))return money(v);if(['attendance','tickets','merch'].includes(g.kind))return Math.round(v*100)+'%';if(['wins','homegrown','young'].includes(g.kind))return v+' / '+g.target;if(g.kind==='efficient')return v>state.teams.length?'Outside playoff places':'Payroll rank '+v;return ownerGoalMet(club,g)?'On track':'Not yet met'}
function ownerSettle(club,g){if(g.status!=='pending')return;const owner=ownerFor(club);g.status=ownerGoalMet(club,g)?'met':'failed';owner.patience=owner.fired?0:Math.max(0,Math.min(100,owner.patience+(g.status==='met'?Math.ceil(g.weight/2):-g.weight)));if(club.id===controlledTeamId())say('OWNER REVIEW: '+ownerGoalLabel(club,g)+' — '+g.status+'. Patience '+owner.patience+'%.');if(owner.patience===0)owner.fired=true}
function ownerTrack(){for(const club of state.teams){if(expansionPendingSeason(club))continue;const owner=ownerFor(club),plan=owner.plan;financeFor(club);plan.maxPayroll=Math.max(plan.maxPayroll,ownerPayroll(club));const star=club.roster.find(p=>p.id===plan.star);if(!plan.adapted&&star&&state.day<seasonLength()*.35&&injuryDays(star)>=seasonLength()-state.day){plan.adapted=true;for(const g of plan.goals)if(g.status==='pending'&&['title','wins','playoffs','final'].includes(g.kind)){g.kind='wins';g.target=club.w+Math.ceil(state.schedule.slice(state.day).filter(r=>r.some(p=>p.includes(club.id))).length*.4);g.deadline=seasonLength()}if(club.id===controlledTeamId())say('OWNER UPDATE: '+star.name+' faces a long absence. Expectations revised to staying competitive; no championship mandate.')}for(const g of plan.goals)if(g.status==='pending'&&g.deadline<seasonLength()&&state.day>=g.deadline)ownerSettle(club,g)}}
function ownerDay(){ownerTrack();for(const club of state.teams){if(expansionPendingSeason(club))continue;financeDay(club);const plan=ownerFor(club).plan;if(state.day===seasonLength())for(const g of plan.goals)if(g.deadline===seasonLength())ownerSettle(club,g)}}

function ownerFinalize(){ownerDay();if(state.champion!==null)financeFinalize();for(const club of state.teams){if(expansionPendingSeason(club))continue;const owner=ownerFor(club),plan=owner.plan;if(owner.history.some(h=>h.year===state.year))continue;for(const g of plan.goals)ownerSettle(club,g);owner.history.push({year:state.year,wins:club.w,games:ownerGames(club),playoffs:ownerPlayoffClub(club),title:state.champion===club.id,merchPerHome:plan.homeGames?plan.merch/plan.homeGames:plan.baseMerch});owner.history=owner.history.slice(-8);const c=owner.campaign,years=state.year-c.startYear+1;
 const settle=(kind,met)=>{if(c.settled.includes(kind))return;c.settled.push(kind);owner.patience=owner.fired?0:Math.max(0,Math.min(100,owner.patience+(met?15:-20)));if(club.id===controlledTeamId())say('OWNER LONG-TERM REVIEW: '+kind+' — '+(met?'met':'failed')+'.');if(owner.patience===0)owner.fired=true};
 if(years===2&&owner.type==='rebuilder')settle('Turnaround',club.w/ownerGames(club)>=Math.min(1,c.baseWins/c.baseGames+15/82));if(years===3&&['penny','hometown'].includes(owner.type))settle('Consistent contender',owner.history.filter(h=>h.year>=c.startYear).slice(-3).every(h=>h.playoffs));if(years===4&&owner.type==='tycoon')settle('Build a dynasty',owner.history.filter(h=>h.year>=c.startYear&&h.title).length>=2);
 }}
function ownerNewSeason(){for(const club of state.teams){const owner=ownerFor(club);if(state.year-owner.campaign.startYear>=4){const h=owner.history.at(-1);owner.campaign={startYear:state.year,baseWins:h?.wins||0,baseGames:h?.games||ownerGames(club),settled:[]}}}}
function ownerCanManage(){return simulationAutopilot()||(controlledTeamId()>=0&&!ownerFor(team()).fired)}
function ownerDismissal(){return '<section class="panel owner-dismissal"><div class="eyebrow">EMPLOYMENT ENDED</div><h2>You have been relieved of your duties.</h2><p>Ownership patience reached 0%. This career remains available to load and export.</p><button class="primary" onclick="returnToTitle()">Save and return to title</button>'+ownerPanel()+'</section>'}
async function ownerTicketPrice(value){const plan=ownerFor(team()).plan,n=Number(value);if(!ownerCanManage()||!Number.isFinite(n)||n<plan.baseTicket*.5||n>plan.baseTicket*2)return toast('Ticket price must be between $37.50 and $150.');const old=plan.ticketPrice;plan.ticketPrice=n;if(!await save()){plan.ticketPrice=old;return toast('Could not save ticket price.')}render()}
function ownerPanel(){const club=team(),owner=ownerFor(club),plan=owner.plan,c=owner.campaign,projection=ownerBusinessProjection(club,plan);return `<section class="panel owner-panel"><div class="panelhead"><div><div class="eyebrow">OWNERSHIP · ${state.year}</div><h2>${OWNER_TYPES[owner.type].name}</h2><p>${OWNER_TYPES[owner.type].description}</p></div><div class="owner-patience"><strong>${owner.patience}%</strong><span>OWNER PATIENCE</span><meter min="0" max="100" value="${owner.patience}">${owner.patience}</meter></div></div><div class="owner-body">${plan.adapted?'<p class="owner-adjustment">Major injury adjustment: championship expectations replaced with a competitive win target.</p>':''}<div class="owner-goals">${plan.goals.map(g=>`<article class="owner-goal"><div><strong>${escapeHTML(ownerGoalLabel(club,g))}</strong><small>${g.deadline===seasonLength()+1?'Postseason review':g.deadline===seasonLength()?'Season-end review':'Day '+g.deadline+' review'} · Miss: −${g.weight} patience</small></div><div><span class="owner-status ${g.status}">${g.status==='pending'?ownerGoalDisplay(club,g):g.status.toUpperCase()}</span></div></article>`).join('')}</div><div class="owner-business"><div><h3>Fan &amp; business dashboard</h3><p>Attendance <strong>${plan.homeGames?Math.round(plan.attendanceSum/plan.homeGames*100)+'%':'—'}</strong> · ${plan.homeGames} tracked home games</p><p>Revenue ${money(plan.revenue)} · Costs ${money(plan.costs)} · Profit ${money(plan.revenue-plan.costs)}</p><p>Merchandise ${money(plan.merch)} · Projected next-home attendance ${Math.round(projection.attendance*100)}%</p><label>Average ticket price ($)<input type="number" min="37.5" max="150" step=".5" value="${plan.ticketPrice}" onchange="ownerTicketPrice(this.value)" ${owner.fired?'disabled':''}></label><small>Detailed revenue, daily payroll, operating budgets and progressive luxury tax are tracked in the Finances tab. Tracking begins day ${plan.startDay+1}.</small></div><div><h3>Long-term ownership plan</h3>${owner.type==='rebuilder'?`<p>Turnaround · by ${c.startYear+1}: improve win rate by ${(15/82*100).toFixed(1)} points over the baseline (${c.baseWins} / ${c.baseGames}). ${c.settled.includes('Turnaround')?'Reviewed.':''}</p>`:''}${['penny','hometown'].includes(owner.type)?`<p>Consistent contender · ${c.startYear}–${c.startYear+2}: reach the playoffs each season. ${c.settled.includes('Consistent contender')?'Reviewed.':''}</p>`:''}${owner.type==='tycoon'?`<p>Build a dynasty · by ${c.startYear+3}: two titles in four seasons. ${owner.history.filter(h=>h.year>=c.startYear&&h.title).length} / 2</p>`:''}<small>Win targets scale to league length. Draft lottery and award goals are not assigned until those competitions exist. Goals settle once; reaching 0% patience ends employment.</small></div></div></div></section>`}
function readOwner(raw,bad){
 if(raw===undefined)return undefined;
 const number=(v,min,max)=>typeof v==='number'&&Number.isFinite(v)&&v>=min&&v<=max,integer=(v,min,max)=>Number.isInteger(v)&&number(v,min,max);
 if(!raw||!Object.hasOwn(OWNER_TYPES,raw.type)||!integer(raw.patience,0,100)||typeof raw.fired!=='boolean'||raw.fired&&raw.patience!==0||!Array.isArray(raw.history)||raw.history.length>8||!raw.campaign)bad('invalid owner.');
 const c=raw.campaign;if(!integer(c.startYear,1900,10000)||!integer(c.baseWins,0,120)||!integer(c.baseGames,0,120)||!Array.isArray(c.settled)||c.settled.length>3||c.settled.some(x=>!['Turnaround','Consistent contender','Build a dynasty'].includes(x)))bad('invalid owner campaign.');
 const history=raw.history.map(h=>{if(!h||!integer(h.year,1900,10000)||!integer(h.wins,0,120)||!integer(h.games,0,120)||h.wins>h.games||typeof h.playoffs!=='boolean'||typeof h.title!=='boolean'||!number(h.merchPerHome,0,100))bad('invalid owner history.');return {year:h.year,wins:h.wins,games:h.games,playoffs:h.playoffs,title:h.title,merchPerHome:h.merchPerHome}});
 let plan=null;if(raw.plan){const p=raw.plan;for(const k of ['year','startDay','lastDay','icon','iconTerm','homeGames','games'])if(!integer(p[k],0,10000000))bad('invalid owner season.');if(p.startDay>366||p.lastDay>366||p.homeGames>120||p.games>120||p.homeGames>p.games||p.year<1900||p.year>10000||p.iconTerm<1900||p.iconTerm>10000)bad('invalid owner season bounds.');for(const k of ['basePayroll','maxPayroll','baseTicket','ticketPrice','attendanceSum','ticketSum','merch','revenue','costs','baseMerch'])if(!number(p[k],0,1000000000))bad('invalid owner finances.');if(p.baseTicket!==75||p.ticketPrice<10||p.ticketPrice>300||p.baseMerch<=0||typeof p.adapted!=='boolean'||!(p.star===null||integer(p.star,0,10000000))||!Array.isArray(p.initialIds)||p.initialIds.length>30||p.initialIds.some(id=>!integer(id,0,10000000))||!Array.isArray(p.goals)||p.goals.length>8)bad('invalid owner goals.');
 const goals=p.goals.map(g=>{if(!g||!OWNER_GOAL_KINDS.includes(g.kind)||!number(g.target,0,10000000)||!integer(g.weight,1,40)||!integer(g.deadline,1,367)||!['pending','met','failed'].includes(g.status))bad('invalid owner goal.');return {kind:g.kind,target:g.target,weight:g.weight,deadline:g.deadline,status:g.status}});
 plan={...Object.fromEntries(['year','startDay','lastDay','basePayroll','maxPayroll','baseTicket','ticketPrice','icon','iconTerm','star','adapted','homeGames','games','attendanceSum','ticketSum','merch','revenue','costs','baseMerch'].map(k=>[k,p[k]])),initialIds:[...p.initialIds],goals};}
 return {type:raw.type,patience:raw.patience,fired:raw.fired,history,campaign:{startYear:c.startYear,baseWins:c.baseWins,baseGames:c.baseGames,settled:[...c.settled]},plan};
}

const rosterCoachBeforeOwners=coachRosterCard;
coachRosterCard=function(club){const owner=ownerFor(club);return rosterCoachBeforeOwners(club)+'<section class="panel"><div class="panelhead"><div><span class="eyebrow">OWNERSHIP</span><h2>'+OWNER_TYPES[owner.type].name+'</h2></div><span>Patience '+owner.patience+'%</span></div></section>'};

// Only the successful new-career flow opens this letter; loading a save does not.
function ownerWelcomeContent(fromInbox=false){
 const club=team(),owner=ownerFor(club),name=escapeHTML(club.city+' '+club.name),gm=escapeHTML(state.gmName||'General Manager');
 const letters={balanced:'Welcome aboard. Build a competitive team and a sustainable business. I expect steady progress, responsible spending, and playoff basketball.',
  tycoon:'We hired you to build a champion. I will tolerate an expensive roster when the results justify it, but I expect us to compete at the highest level. Make every move count.',
  penny:'This franchise needs to compete without losing control of its finances. Find value, manage our payroll, and build a team that can win sustainably. A big name alone will not justify a big bill.',
  hometown:'This team belongs to its fans as much as it belongs to me. Give our city a team it can believe in, look after the players who have earned its loyalty, and make our arena a place people want to be.',
  rebuilder:'We are building for more than one season. Give our young players meaningful opportunities and make decisions that leave this franchise stronger. I can be patient with losses when there is a clear plan and real progress.'
 };
 return `<div class="owner-welcome-head"><div class="eyebrow">A MESSAGE FROM OWNERSHIP</div><button type="button" aria-label="Close owner welcome" onclick="document.getElementById('owner-welcome').close()">✕</button></div><div class="owner-welcome-team">${teamLogo(club)}<div><span>${seasonLabel(state.year)} SEASON</span><h2 id="owner-welcome-title">Welcome to ${name}.</h2><p>${escapeHTML(OWNER_TYPES[owner.type].name)}</p></div></div><div class="owner-welcome-letter"><p><strong>${gm},</strong></p><p>${letters[owner.type]}</p><p>You have the keys to our basketball operations. These are the priorities I will be judging this season:</p><ul>${owner.plan.goals.map(g=>`<li>${escapeHTML(ownerGoalLabel(club,g))}<small>${g.deadline===seasonLength()+1?'Postseason review':g.deadline===seasonLength()?'Season-end review':'Review on day '+g.deadline}</small></li>`).join('')}</ul><div class="owner-welcome-facts"><div><span>OWNER PATIENCE</span><strong>${owner.patience}%</strong></div><div><span>TEAM PAYROLL</span><strong>${money(ownerPayroll(club))}</strong></div><div><span>SALARY CAP</span><strong>${money(salaryCap())}</strong></div></div><p class="owner-welcome-signoff">Let’s get to work.<br><strong>Ownership · ${name}</strong></p></div><footer class="owner-welcome-footer"><small>Review your owner’s goals in Front office.</small><button type="button" class="primary" autofocus onclick="document.getElementById('owner-welcome').close()">${fromInbox?'Back to Inbox':'Go to Dashboard →'}</button></footer>`;
}
function showOwnerWelcome(fromInbox=false){
 let dialog=document.getElementById('owner-welcome');
 if(!dialog){dialog=document.createElement('dialog');dialog.id='owner-welcome';dialog.className='owner-welcome';dialog.setAttribute('aria-labelledby','owner-welcome-title');document.body.appendChild(dialog)}
 dialog.innerHTML=ownerWelcomeContent(fromInbox);dialog.showModal();
}
